from pathlib import Path
import hashlib,json,re,tarfile,subprocess
root=Path.cwd(); ev=root/'evidence/s02-candidate-a-completion/a3/task1';src=root/'.superpowers/sdd/a3-task1-receipts'
h=lambda b:hashlib.sha256(b).hexdigest()
errors=[]; entries=[]
def check(ok,label):
 if not ok:errors.append(label)
with tarfile.open(ev/'author-evidence.tar.gz','r:gz') as t:
 for member in t:
  if member.isfile():
   raw=t.extractfile(member).read();check((root/member.name).read_bytes()==raw,'archive-original:'+member.name)
   entries.append({'path':member.name,'bytes':len(raw),'sha256':h(raw)})
closures={}
for stage,test in [('red','literal-fidelity.json'),('green','task1-tests.json')]:
 r=json.loads((src/stage/test).read_text());closures[stage]=r['sourceClosure']
 check(r['exitCode']==(1 if stage=='red' else 0),'terminal:'+stage)
 check(r['chunks'][-1].get('exit_code')==r['exitCode'],'raw-terminal:'+stage)
 output=''.join(x.get('output','')for x in r['chunks'])
 if stage=='red':check('QNT508' in output and '1 failed' in output,'behavioral-red')
 else:check(re.findall(r'ok (\w+Test) passed',output)==['literalFidelityTest','authorityTimeZeroTest'] and '2 passing' in output,'complete-green-inventory')
 for f in r['sourceClosure']:
  raw=(src/stage/'source'/f['path']).read_bytes();check(h(raw)==f['sha256'],'snapshot:'+stage+':'+f['path'])
  if stage=='green':check((root/f['path']).read_bytes()==raw,'live:'+f['path'])
  if 'candidate_a_authority_swap_' not in f['path']:check(subprocess.check_output(['git','show','d14cfea98a1c9213e5ef5f12c1a088f4e966083d:'+f['path']])==raw,'frozen:'+f['path'])
 check(len(r['sourceClosure'])==14,'closure-size:'+stage)
 for part in [r['tool'],r['tool']['backend']]:check(h(Path(part['path']).read_bytes())==part['sha256'],'tool:'+part['path'])
 for name in ['candidate_a_authority_swap_fixtures','candidate_a_authority_swap_test']:
  tc=json.loads((src/stage/(name+'-typecheck.json')).read_text());check(tc['exitCode']==0 and tc['chunks'][-1].get('exit_code')==0,'typecheck:'+stage+name)
  check({x['path']:x['sha256'] for x in tc['sourceClosure']}=={x['path']:x['sha256'] for x in r['sourceClosure']},'typecheck-closure:'+stage+name)
fixture='specs/quint/s02/candidate_a_authority_swap_fixtures.qnt'
red=(src/'red/source'/fixture).read_text();green=(src/'green/source'/fixture).read_text()
check(red.replace('if (settlement) 2 else if (s.mode == RefundS) 3 else 1 + s.funded','if (settlement or s.mode == RefundS) 3 else 1 + s.funded')==green,'exact-red-correction')
check({x['path']:x['sha256'] for x in closures['red'] if x['path']!=fixture}=={x['path']:x['sha256'] for x in closures['green'] if x['path']!=fixture},'only-fixture-changed')
review=(ev/'independent-review.md').read_text()
check(all(x in review for x in ['fb407555584e167ae0fddc3e59fbf6d64ecd79a00d2ad03d02f159da8429ed15','1113f8a8c69de0832644248aba907ab62d5a2c97a209638c6aed3c7e7a61645b','approved']),'review-pins')
print(json.dumps({'status':'local-A3-Task1-accepted' if not errors else 'open-a3-task1','errors':errors,'archive':{'sha256':h((ev/'author-evidence.tar.gz').read_bytes()),'members':entries},'greenSourceClosure':closures['green'],'limits':['Author-executed runtime independently source/receipt audited; root did not duplicate tests','No profile lifecycle, Council, model checking or full A3 acceptance']},indent=2))
raise SystemExit(bool(errors))
PY

